(let [c (seon.operator/connection "faults-render") d @c p (seon.schema/projection-from-database d)] (seon.schema/call-with-projection p (fn [] (let [settings (seon.config/effective d "faults-render") turn (seon.db/q '[:find ?r . :where [?a :seon.cluster.agent/id "juniper"] [?r :seon.cluster.run/agent ?a] [?r :seon.cluster.run/reply]] d) fault (assoc (seon.error/normalize {:seon.error/source {:seon.error/kind :seon.probe/render-fault :seon.error/message "Render pair verification."} :seon.error/id "faults-render-presentation-probe" :seon.error/at (java.util.Date.) :seon.error/process "faults-render-probe" :seon.sci.admit/caps (seon.config/result-caps settings) :seon.config.error/max-evidence-bytes (:seon.config.error/max-evidence-bytes settings)}) :seon.error/agent [:seon.cluster.agent/id "juniper"] :seon.error/run turn :seon.instrument/fn "seon.ai/complete") written (seon.db/transact! c [fault])] {:seon.probe/committed? (not (:seon.error/kind written)) :seon.probe/ai (seon.error/render-ai fault) :seon.probe/html (seon.error/render-html fault)}))))
